var rows = StratagemManager.get_fire_overwatch_offer_targets_11e(2)
var ids = []
for r in rows:
	ids.append(str(r.unit_id))
ids.sort()
return ids

var rec = {"opened": [], "dialog": 0}
var ph = PhaseManager.get_current_phase_instance()
ph.stratagem_window_opened.connect(func(p, w, offers, _ctx):
	var ids = []
	for o in offers:
		ids.append(str(o.get("stratagem_id", "")))
	rec["opened"].append([p, w, ids]))
tree.node_added.connect(func(n):
	if str(n.name) == "StratagemDialog":
		rec["dialog"] += 1)
tree.current_scene.set_meta("fo_skip_rec", rec)
return true

var rec = tree.current_scene.get_meta("fo_skip_rec")
for o in rec["opened"]:
	if int(o[0]) == 2 and str(o[1]) == "movement_phase_end" and o[2] == ["fire_overwatch_11e"]:
		return true
return rec["opened"]

var n = 0
for u in StratagemManager._usage_history.get("2", []):
	if str(u.stratagem_id) == "fire_overwatch_11e":
		n += 1
return n
